-- 2026-11-12 — Seller desk: the seller books for a walk-in customer from his own dashboard, pays the platform with his e-wallet
-- (Kashier wallet, same worker endpoints as the site) and the customer receives the voucher by e-mail / WhatsApp.
--
--  * seller_quote(p)      – the exact price the server will charge (same compute_booking_price create_booking checks). Sellers only.
--  * public_voucher(id)   – a seller booking's voucher for the CUSTOMER, who has no account. The booking id is the secret: sellers' ids are
--                           generated by the dashboard with >= 22 random characters, and only confirmed seller bookings are served here.
--
-- create_booking already attributes a booking made from a seller's own account to him (commission), unless the guest e-mail is his own.

create or replace function public.seller_quote(p jsonb)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  v_type text := p->>'type';
  v_id   text;
  v_prop public.properties;
begin
  if not (select public.is_seller()) then raise exception 'forbidden' using errcode = '42501'; end if;
  if jsonb_typeof(p) <> 'object' or v_type not in ('hotel', 'excursion', 'transfer', 'package') then raise exception 'Unknown booking type' using errcode = '22023'; end if;
  v_id := p->>(case v_type when 'hotel' then 'hotelId' when 'excursion' then 'excursionId' when 'package' then 'packageId' else 'transferId' end);
  select * into v_prop from public.properties where id = v_id and kind = v_type::public.property_kind and status = 'published';
  if not found then raise exception 'Item not found' using errcode = 'P0002'; end if;
  return public.compute_booking_price(p, v_prop.data);
end $$;
revoke all on function public.seller_quote(jsonb) from public, anon;
grant execute on function public.seller_quote(jsonb) to authenticated;

create or replace function public.public_voucher(p_id text)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_row public.bookings;
begin
  if coalesce(p_id, '') !~ '^[A-Za-z0-9_-]{20,64}$' then return null; end if;
  select * into v_row from public.bookings where id = p_id and seller_id is not null and status = 'completed';
  if not found then return null; end if;
  return public.booking_to_json(v_row) - array['uid', 'ownerUid', 'ownerStatus', 'ownerNote', 'adminNote', 'ownerShare', 'earning', 'commission',
                                              'sellerAmount', 'sellerName', 'platformNet', 'commissionRate', 'payment'];
end $$;
revoke all on function public.public_voucher(text) from public;
grant execute on function public.public_voucher(text) to anon, authenticated;

-- the seller sees contact details only of bookings he made himself from his dashboard (he typed them in): needed to resend the voucher
create or replace function public.seller_bookings(p_seller uuid default null, p_limit integer default 500)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_s uuid := coalesce(p_seller, (select auth.uid()));
begin
  if v_s is distinct from (select auth.uid()) and not (select public.is_super_admin()) then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', b.id, 'type', b.kind, 'status', b.status, 'createdAt', b.created_at, 'serviceDate', coalesce(b.check_in, b.service_date),
      'customer', case when b.user_id = v_s then coalesce(b.guest_name, '') else split_part(coalesce(b.guest_name, ''), ' ', 1) end,
      'phone', case when b.user_id = v_s then b.guest_phone end, 'email', case when b.user_id = v_s then b.guest_email end,
      'plan', b.payment_plan, 'paidNow', b.amount_due_now, 'onSite', b.remaining_amount,
      'item', coalesce(b.data->'hotelName'->>'en', b.data->'hotelName'->>'ar', b.data->>'hotelName', b.data->'title'->>'en', b.data->'title'->>'ar', b.data->>'title', b.data->>'vehicleType', ''),
      'subtotal', b.subtotal, 'rate', round(coalesce(b.seller_rate, 0) * 100, 2), 'amount', b.seller_amount, 'currency', b.currency,
      'earnedAt', b.earned_at, 'void', b.earning_void, 'viaOwnAccount', b.user_id = v_s) order by b.created_at desc)
    from (select * from public.bookings where seller_id = v_s and status <> 'pending_payment' and status <> 'failed'
           order by created_at desc limit least(greatest(p_limit, 1), 2000)) b
  ), '[]'::jsonb);
end $$;
grant execute on function public.seller_bookings(uuid, integer) to authenticated;

-- make PostgREST see the new functions right away
notify pgrst, 'reload schema';
